@page "/notepad"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject IJSRuntime JS

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea @bind="Content" @bind:event="oninput" rows="15" style="width:100%;"></textarea>

<div style="margin-top:0.5rem; display:flex; align-items:center; gap:1rem;">
    <button @onclick="SaveNowAsync">Save now</button>
    <button @onclick="ClearAsync">Clear</button>
    @if (_lastSaved is not null)
    {
        <span>Last saved at @_lastSaved.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string Content { get; set; } = string.Empty;
    private string _savedSnapshot = string.Empty;
    private DateTime? _lastSaved;
    private NotepadInterop? _interop;
    private Timer? _autoSaveTimer;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            Content = await _interop.LoadAsync() ?? string.Empty;
            _savedSnapshot = Content;

            _autoSaveTimer = new Timer(async _ =>
            {
                await InvokeAsync(async () =>
                {
                    await PersistContentAsync();
                    StateHasChanged();
                });
            }, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));

            StateHasChanged();
        }
    }

    private bool HasUnsavedChanges => Content != _savedSnapshot;

    private async Task SaveNowAsync() => await PersistContentAsync();

    private async Task ClearAsync()
    {
        Content = string.Empty;
        _savedSnapshot = string.Empty;
        _lastSaved = null;

        if (_interop is not null)
        {
            await _interop.ClearAsync();
            await _interop.SetBeforeUnloadAsync(false);
        }
    }

    private async Task PersistContentAsync()
    {
        if (_interop is null) return;

        await _interop.SaveAsync(Content);
        _savedSnapshot = Content;
        _lastSaved = DateTime.Now;
        await _interop.SetBeforeUnloadAsync(false);
    }

    private async Task OnContentChanged()
    {
        if (_interop is not null && HasUnsavedChanges)
        {
            await _interop.SetBeforeUnloadAsync(true);
        }
    }

    // Called by the textarea binding pipeline — keep beforeunload in sync
    public string GetContent() => Content;

    protected override async Task OnParametersSetAsync()
    {
        // Not used for parameter changes but keeping the beforeunload guard
    }

    public async ValueTask DisposeAsync()
    {
        if (_autoSaveTimer is not null)
        {
            await _autoSaveTimer.DisposeAsync();
        }

        if (_interop is not null)
        {
            await _interop.DisposeAsync();
        }
    }
}

